const textExtensions = new Set(['.html', '.js', '.css', '.json']);
const runtimeExtensions = new Set([...textExtensions, '.png', '.webp', '.jpg', '.jpeg', '.gif', '.svg', '.ogg', '.mp3', '.wav', '.woff', '.woff2']);
